import { Component, OnInit, Output, EventEmitter } from '@angular/core';
import { Email } from '../../../../core/models/email.model';
import { EmailService } from '../../../../core/services/email.service';

@Component({
  selector: 'app-email-preview',
  templateUrl: './email-preview.component.html',
  styleUrls: ['./email-preview.component.scss']
})
export class EmailPreviewComponent implements OnInit {
  @Output() deleted = new EventEmitter<Email>();

  email: Email | null = null;

  constructor(private emailService: EmailService) {}

  ngOnInit(): void {
    this.emailService.selectedEmail$.subscribe(email => {
      this.email = email;
    });
  }

  getInitials(name: string): string {
    return name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
  }

  formatFullDate(timestamp: string): string {
    return new Date(timestamp).toLocaleString('en-IN', {
      weekday: 'long', year: 'numeric', month: 'long',
      day: 'numeric', hour: '2-digit', minute: '2-digit'
    });
  }

  toggleStar(): void {
    if (this.email) this.emailService.toggleStar(this.email);
  }

  deleteEmail(): void {
    if (this.email) {
      this.emailService.deleteEmail(this.email);
    }
  }

  getAttachmentIcon(type: string): string {
    const icons: Record<string, string> = {
      pdf: '📄', image: '🖼️', doc: '📃', zip: '📦', other: '📎'
    };
    return icons[type] || icons['other'];
  }
}
<div class="preview" *ngIf="email; else noSelection">
  <!-- Toolbar -->
  <div class="preview__toolbar">
    <div class="preview__toolbar-left">
      <button class="preview__tool-btn preview__tool-btn--star"
        (click)="toggleStar()"
        [class.active]="email.isStarred"
        title="Star">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path d="M8 1.5l1.763 3.57 3.937.574-2.85 2.777.673 3.923L8 10.27l-3.523 1.85.673-3.923L2.3 5.644l3.937-.574L8 1.5z"
            [attr.fill]="email.isStarred ? '#f59e0b' : 'none'"
            [attr.stroke]="email.isStarred ? '#f59e0b' : 'currentColor'"
            stroke-width="1.2" stroke-linejoin="round"/>
        </svg>
      </button>

    </div>

    <div class="preview__toolbar-right">
      <button class="preview__tool-btn preview__tool-btn--danger" (click)="deleteEmail()" title="Delete">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path d="M3 5h10M6 5V3h4v2M4 5l1 9h6l1-9"
            stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </button>
    </div>
  </div>

  <!-- Email content -->
  <div class="preview__content">
    <!-- Subject 
    <h1 class="preview__subject">{{ email.subject }}</h1>-->

    <!-- Sender info -->
    <div class="preview__meta">
      <div class="preview__avatar" [style.background]="email.avatarColor">
        <img 
       *ngIf="email.avatarImage"
       [src]="email.avatarImage"
       [alt]="email.sender"
       style="width: 100%;height: 100%;object-fit: cover;border-radius: 50%; display: block;">
    <span *ngIf="!email.avatarImage"> {{ getInitials(email.sender) }}</span>
      </div>
      <div class="preview__sender-info">
        <div class="preview__sender-row">
          <strong class="preview__sender-name">{{ email.sender }}</strong>
          <span class="preview__date">{{ formatFullDate(email.timestamp) }}</span>
        </div>
        <p class="preview__sender-email">{{ email.senderEmail }}</p>
      </div>
    </div>

    <!-- Tags 
    <div class="preview__tags" *ngIf="email.tags.length > 0">
      <span class="preview__tag" *ngFor="let tag of email.tags">{{ tag }}</span>
    </div>-->

    <!-- Body -->
    <div class="preview__body" [innerHTML]="email.body"></div>

    <!-- Attachments -->
  </div>
</div>

<!-- No selection state -->
<ng-template #noSelection>
  <div class="preview preview--empty">
    <div class="preview__empty-content">
      <svg width="64" height="64" viewBox="0 0 64 64" fill="none">
        <rect x="8" y="16" width="48" height="36" rx="5" stroke="currentColor" stroke-width="1.5" stroke-opacity="0.2"/>
        <path d="M8 26l24 16 24-16" stroke="currentColor" stroke-width="1.5" stroke-opacity="0.2"/>
      </svg>
      <h3>Select an email</h3>
      <p>Choose a message from the list to read it here</p>
    </div>
  </div>
</ng-template>
